$ErrorActionPreference = "Stop"

$ProjectRoot = "H:\MNTrapTeam\MNTrapTeam"
$Version = "4.5.2"

if (-not (Test-Path (Join-Path $ProjectRoot "mntrapteam"))) {
    throw "MNTrapTeam project not found at $ProjectRoot"
}

Write-Host "Installing MNTrapTeam $Version scout name diagnostic..."

$payload = ""
[IO.File]::WriteAllBytes(
    (Join-Path $ProjectRoot "mntrapteam\recent_score_scout_cli.py"),
    [Convert]::FromBase64String($payload)
)

Set-Content -Path (Join-Path $ProjectRoot "VERSION") -Value $Version -Encoding UTF8

$InitFile = Join-Path $ProjectRoot "mntrapteam\__init__.py"
if (Test-Path $InitFile) {
    $t = Get-Content $InitFile -Raw
    if ($t -match '__version__\s*=') {
        $t = [regex]::Replace(
            $t,
            '__version__\s*=\s*["''][^"'']+["'']',
            '__version__ = "4.5.2"',
            1
        )
    } else {
        $t = $t.TrimEnd() + "`r`n__version__ = `"4.5.2`"`r`n"
    }
    Set-Content -Path $InitFile -Value $t -Encoding UTF8
}

Set-Location $ProjectRoot
& ".\.venv\Scripts\python.exe" -m py_compile ".\mntrapteam\recent_score_scout_cli.py"
if ($LASTEXITCODE -ne 0) { throw "Syntax check failed." }

Write-Host ""
Write-Host "MNTrapTeam 4.5.2 installed."
Write-Host "Added --debug-name raw-row diagnostic."
Write-Host ""
Write-Host "Run:"
Write-Host '& ".\.venv\Scripts\python.exe" -m mntrapteam.recent_score_scout_cli preview --id-scan 2050:2140 --debug-name LARSON'
